package com.estradaplay.comunista;
import android.content.Context;import android.content.SharedPreferences;import org.json.*;import java.util.*;
final class VehicleProfileStore{
 static final String P="epc_vehicle_profiles_v160",K="profiles",A="active";
 static final class Profile{final String id,name,type;final float kmL,fuelPrice,tankL,fuelPercent;Profile(String i,String n,String t,float k,float p,float tank,float pct){id=i==null||i.isEmpty()?String.valueOf(System.currentTimeMillis()):i;name=n==null||n.trim().isEmpty()?"Meu veículo":n.trim();type=t==null||t.trim().isEmpty()?"Carro":t.trim();kmL=Math.max(1,k);fuelPrice=Math.max(0,p);tankL=Math.max(1,tank);fuelPercent=Math.max(0,Math.min(100,pct));}float autonomyKm(){return tankL*(fuelPercent/100f)*kmL;}JSONObject json(){JSONObject o=new JSONObject();try{o.put("id",id);o.put("name",name);o.put("type",type);o.put("kml",kmL);o.put("price",fuelPrice);o.put("tank",tankL);o.put("pct",fuelPercent);}catch(Throwable ignored){}return o;}static Profile from(JSONObject o){if(o==null)return null;return new Profile(o.optString("id"),o.optString("name","Meu veículo"),o.optString("type","Carro"),(float)o.optDouble("kml",10),(float)o.optDouble("price",0),(float)o.optDouble("tank",50),(float)o.optDouble("pct",50));}}
 static SharedPreferences p(Context c){return c.getSharedPreferences(P,Context.MODE_PRIVATE);}static ArrayList<Profile> list(Context c){ArrayList<Profile> out=new ArrayList<>();try{JSONArray a=new JSONArray(p(c).getString(K,"[]"));for(int i=0;i<a.length();i++){Profile x=Profile.from(a.optJSONObject(i));if(x!=null)out.add(x);}}catch(Throwable ignored){}if(out.isEmpty()){android.content.SharedPreferences legacy=c.getSharedPreferences("epc_drive_settings_v140",Context.MODE_PRIVATE);float lk=Math.max(1f,legacy.getFloat("consumption_kml",10f));float lp=Math.max(0f,legacy.getFloat("fuel_price",0f));Profile d=new Profile("default","Meu veículo","Carro",lk,lp,50,50);out.add(d);saveAll(c,out);p(c).edit().putString(A,d.id).apply();}return out;}static Profile active(Context c){ArrayList<Profile> a=list(c);String id=p(c).getString(A,"");for(Profile x:a)if(x.id.equals(id))return x;return a.get(0);}static void setActive(Context c,String id){p(c).edit().putString(A,id==null?"":id).apply();}static void save(Context c,Profile x){ArrayList<Profile>a=list(c);boolean found=false;for(int i=0;i<a.size();i++)if(a.get(i).id.equals(x.id)){a.set(i,x);found=true;break;}if(!found)a.add(x);saveAll(c,a);setActive(c,x.id);}static void remove(Context c,String id){ArrayList<Profile>a=list(c);a.removeIf(x->x.id.equals(id));if(a.isEmpty())a.add(new Profile("default","Meu veículo","Carro",10,0,50,50));saveAll(c,a);setActive(c,a.get(0).id);}private static void saveAll(Context c,List<Profile>a){JSONArray j=new JSONArray();for(Profile x:a)j.put(x.json());p(c).edit().putString(K,j.toString()).apply();}}
